import React from 'react';

import { NavLink } from 'react-router-dom';

import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import { getRadishList } from '@apps/Hiking/@services/hikingRadish.service';
import { IHikingRadishWithHiking } from '@apps/Hiking/@types/hikingRadish.types';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

const RadishOnePage = ({ id_user }: { id_user: number }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IHikingRadishWithHiking[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getRadishList(id_user);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_user]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PohLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  return (
    <div title="Редиски">
      <PohBreadcrumbs
        data={[
          { href: '/radish', text: 'Редиски' },
          {
            href: `/hiking/${id_user}`,
            text: [data[0].user.name, data[0].user.surname].join(' '),
            active: true,
          },
        ]}
      />
      <PohRow>
        <PohCol sm={12} className="" style={{ gap: 12 }}>
          <PohList
            data={data.map((item) => {
              return {
                key: item.id,
                children: (
                  <div className="d-flex">
                    <PohAva
                      src={item.user.photo}
                      alt={[item.user.name, item.user.surname].join(' ')}
                      className="me-2"
                    />
                    <div>
                      <strong className="d-block">
                        {[item.user.name, item.user.surname].join(' ')}
                      </strong>
                      <small className="text-muted d-block">
                        {item.date.toLocaleString()}
                        {item.isHarakiri && <sup className=" text-success"> harakiri</sup>}
                      </small>
                      <small className="text-info">
                        <em>{item.comment}</em>
                      </small>
                    </div>
                    <aside className="ms-auto">
                      <NavLink to={`/hiking/${item.hiking.id}`}>
                        <HikingBadge hiking={item.hiking} />
                      </NavLink>
                    </aside>
                  </div>
                ),
              };
            })}
          />
        </PohCol>
      </PohRow>
    </div>
  );
};

export default RadishOnePage;
